// DOA estimation on synthetic plane waves with arrays other than the Kinect line.
//
// The signals are built from the array geometry directly (not with
// `MusicEstimator::steering_vector`), so the tests check the physical model rather than
// the estimator's agreement with itself. A 2-D array has no θ / 360° − θ mirror
// ambiguity, so every estimate must match the true angle itself.

mod common;

use std::f64::consts::PI;

use musicrs::{MusicError, MusicEstimator, select_bins_by_energy};
use nalgebra::DMatrix;
use num_complex::Complex;

const SPEED_OF_SOUND: f64 = 343.2;
const SAMPLE_RATE: f64 = 16000.0;

/// Square array, 10 cm side, centred on the origin.
fn square_array() -> MusicEstimator {
    MusicEstimator::new(
        vec![[0.05, 0.05], [-0.05, 0.05], [-0.05, -0.05], [0.05, -0.05]],
        720,
        (0.0, 2.0 * PI),
        SAMPLE_RATE,
    )
}

/// Time by which a plane wave from `doa` reaches `p` ahead of the origin.
fn advance(p: [f64; 2], doa: f64) -> f64 {
    (p[0] * doa.cos() + p[1] * doa.sin()) / SPEED_OF_SOUND
}

/// Deterministic pseudo-random values in [0, 1) (LCG).
fn uniform(n: usize, seed: u64) -> Vec<f64> {
    let mut state = seed;
    (0..n)
        .map(|_| {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (state >> 11) as f64 / (1u64 << 53) as f64
        })
        .collect()
}

fn assert_angles(found: &[f64], truths_deg: &[f64], tolerance_deg: f64) {
    let found_deg: Vec<f64> = found.iter().map(|a| a.to_degrees()).collect();
    assert_eq!(found.len(), truths_deg.len(), "got {found_deg:?}");
    for &truth in truths_deg {
        let error = found_deg
            .iter()
            .map(|&f| common::angular_error(f, &[truth]))
            .fold(f64::INFINITY, f64::min);
        assert!(
            error <= tolerance_deg,
            "expected {truth}° among {found_deg:?} (error {error:.2}°)"
        );
    }
}

/// A real-valued tone through `estimate_doa_from_real` is located at its true angle
/// all around the circle, with no mirror image.
#[test]
fn square_array_single_real_source() {
    let est = square_array();
    let freq = 1000.0;
    for doa_deg in [0.0, 50.0, 135.0, 200.0, 300.0] {
        let doa = f64::to_radians(doa_deg);
        let data = DMatrix::from_fn(4, 4000, |m, t| {
            let p = est.antenna_positions[m];
            (2.0 * PI * freq * (t as f64 / SAMPLE_RATE + advance(p, doa))).cos()
        });
        assert_angles(
            &est.estimate_doa_from_real(&data, 1, freq).unwrap(),
            &[doa_deg],
            1.0,
        );
    }
}

/// Two uncorrelated sources at the same frequency, plus a little noise, are both found.
#[test]
fn square_array_two_sources() {
    let est = square_array();
    let freq = 1500.0;
    let n_samples = 4000;
    let doas_deg = [50.0_f64, 200.0];
    let jitter = uniform(n_samples, 3);
    let noise = uniform(8 * n_samples, 5);
    let data = DMatrix::from_fn(4, n_samples, |m, t| {
        let p = est.antenna_positions[m];
        let t_s = t as f64 / SAMPLE_RATE;
        // Source 2 gets a random phase per sample, which decorrelates it from source 1
        let phases = [0.0, 2.0 * PI * jitter[t]];
        let sources: Complex<f64> = doas_deg
            .iter()
            .zip(phases)
            .map(|(&d, phi)| {
                Complex::from_polar(
                    1.0,
                    2.0 * PI * freq * (t_s + advance(p, d.to_radians())) + phi,
                )
            })
            .sum();
        let i = 2 * (m * n_samples + t);
        sources + Complex::new(noise[i] - 0.5, noise[i + 1] - 0.5).scale(0.05)
    });
    assert_angles(&est.estimate_doa(&data, 2, freq).unwrap(), &doas_deg, 1.0);
}

/// MUSIC needs uncorrelated sources. Two plane waves of the same tone with a fixed phase
/// relation (two loudspeakers on one signal, or a reflection) are coherent: the covariance
/// has rank 1, as for a single source, and the estimates land on neither direction. The
/// same two waves with an independent random phase per sample are found exactly.
#[test]
fn coherent_sources_are_not_resolved() {
    let est = square_array();
    let freq = 1500.0;
    let n_samples = 4000;
    let doas_deg = [50.0_f64, 200.0];
    let jitter = uniform(n_samples, 3);
    let waves = |decorrelate: bool| {
        DMatrix::from_fn(4, n_samples, |m, t| {
            let p = est.antenna_positions[m];
            let t_s = t as f64 / SAMPLE_RATE;
            let phases = [
                0.0,
                if decorrelate {
                    2.0 * PI * jitter[t]
                } else {
                    1.0
                },
            ];
            doas_deg
                .iter()
                .zip(phases)
                .map(|(&d, phi)| {
                    Complex::from_polar(
                        1.0,
                        2.0 * PI * freq * (t_s + advance(p, d.to_radians())) + phi,
                    )
                })
                .sum::<Complex<f64>>()
        })
    };
    assert_angles(
        &est.estimate_doa(&waves(true), 2, freq).unwrap(),
        &doas_deg,
        1.0,
    );

    let coherent = est.estimate_doa(&waves(false), 2, freq).unwrap();
    let worst = doas_deg
        .iter()
        .map(|&truth| {
            coherent
                .iter()
                .map(|a| common::angular_error(a.to_degrees(), &[truth]))
                .fold(f64::INFINITY, f64::min)
        })
        .fold(0.0, f64::max);
    println!(
        "coherent: {:?}",
        coherent.iter().map(|a| a.to_degrees()).collect::<Vec<_>>()
    );
    assert!(worst > 5.0, "coherent sources were resolved: {coherent:?}");
}

/// Three sources on a five-element array (the most an n-element array resolves is n − 1).
#[test]
fn pentagon_array_three_sources() {
    let positions: Vec<[f64; 2]> = (0..5)
        .map(|k| {
            let a = 2.0 * PI * k as f64 / 5.0;
            [0.06 * a.cos(), 0.06 * a.sin()]
        })
        .collect();
    let est = MusicEstimator::new(positions, 720, (0.0, 2.0 * PI), SAMPLE_RATE);
    let freq = 1200.0;
    let n_samples = 6000;
    let doas_deg = [30.0_f64, 150.0, 260.0];
    let jitter = uniform(2 * n_samples, 9);
    let noise = uniform(10 * n_samples, 13);
    let data = DMatrix::from_fn(5, n_samples, |m, t| {
        let p = est.antenna_positions[m];
        let t_s = t as f64 / SAMPLE_RATE;
        let phases = [0.0, 2.0 * PI * jitter[t], 2.0 * PI * jitter[n_samples + t]];
        let sources: Complex<f64> = doas_deg
            .iter()
            .zip(phases)
            .map(|(&d, phi)| {
                Complex::from_polar(
                    1.0,
                    2.0 * PI * freq * (t_s + advance(p, d.to_radians())) + phi,
                )
            })
            .sum();
        let i = 2 * (m * n_samples + t);
        sources + Complex::new(noise[i] - 0.5, noise[i + 1] - 0.5).scale(0.05)
    });
    assert_angles(&est.estimate_doa(&data, 3, freq).unwrap(), &doas_deg, 1.0);
}

/// The Kinect line array's spectrum is mirror-symmetric (θ ≡ 360° − θ). A source at
/// endfire that falls between two grid points therefore scores exactly the same on both,
/// and must still be found, at the midpoint between them.
#[test]
fn line_array_endfire_between_grid_points() {
    let half_step = 0.25_f64.to_radians();
    let cases = [
        // 719 steps: 180° lies midway between two grid points
        (
            MusicEstimator {
                angle_steps_num: 719,
                ..MusicEstimator::default()
            },
            180.0,
        ),
        // Grid shifted by half a step: 0° lies midway between -0.25° and 0.25°
        (
            MusicEstimator {
                search_interval: (-half_step, 2.0 * PI - half_step),
                ..MusicEstimator::default()
            },
            0.0,
        ),
    ];
    let freq = 1000.0;
    for (est, doa_deg) in cases {
        let doa = f64::to_radians(doa_deg);
        let data = DMatrix::from_fn(4, 4000, |m, t| {
            let p = est.antenna_positions[m];
            (2.0 * PI * freq * (t as f64 / SAMPLE_RATE + advance(p, doa))).cos()
        });
        assert_angles(
            &est.estimate_doa_from_real(&data, 1, freq).unwrap(),
            &[doa_deg],
            0.01,
        );
    }
}

/// A Kinect-array plane wave at `freq` from `doa_deg`, sampled at the estimator's rate.
fn kinect_tone(est: &MusicEstimator, freq: f64, doa_deg: f64, n_samples: usize) -> DMatrix<f64> {
    let doa = f64::to_radians(doa_deg);
    DMatrix::from_fn(4, n_samples, |m, t| {
        let p = est.antenna_positions[m];
        (2.0 * PI * freq * (t as f64 / est.sample_rate + advance(p, doa))).cos()
    })
}

/// Very loud and very quiet recordings give the same answer: the data is rescaled before
/// its energy and covariance are computed, which would otherwise overflow (or underflow).
#[test]
fn extreme_amplitudes() {
    let est = MusicEstimator {
        search_interval: (0.0, PI),
        angle_steps_num: 360,
        ..MusicEstimator::default()
    };
    let data = kinect_tone(&est, 1000.0, 40.0, 4000);
    let argmax = |s: &[f64]| (0..s.len()).max_by(|&a, &b| s[a].total_cmp(&s[b])).unwrap();
    for amplitude in [1.0, 1e160, 1e300, 1e-160, 1e-300] {
        let scaled = &data * amplitude;
        let found = est.estimate_doa_from_real(&scaled, 1, 1000.0).unwrap();
        assert_eq!(found.len(), 1, "amplitude {amplitude}");
        assert!(
            (found[0].to_degrees() - 40.0).abs() <= 0.5,
            "amplitude {amplitude}: got {found:?}"
        );
        let (spectrum, angles) = est
            .ifb_music_spectrum(&scaled, 160, 1, Some(&[10]))
            .unwrap();
        let peak = angles[argmax(&spectrum)].to_degrees();
        assert!(
            (peak - 40.0).abs() <= 0.5,
            "amplitude {amplitude}: IFB peak {peak}°"
        );
    }
}

/// A quiet tone on a large DC offset is still found, narrowband and with IFB, whose
/// silence check compares each bin with the strongest bin, DC included.
#[test]
fn quiet_tone_on_large_offset() {
    let est = MusicEstimator {
        search_interval: (0.0, PI),
        angle_steps_num: 360,
        ..MusicEstimator::default()
    };
    let data = kinect_tone(&est, 1000.0, 40.0, 4000).map(|x| 1e6 + 1e-5 * x);
    let found = est.estimate_doa_from_real(&data, 1, 1000.0).unwrap();
    assert!((found[0].to_degrees() - 40.0).abs() <= 0.5, "got {found:?}");
    let (spectrum, angles) = est.ifb_music_spectrum(&data, 160, 1, Some(&[10])).unwrap();
    let peak = (0..spectrum.len())
        .max_by(|&a, &b| spectrum[a].total_cmp(&spectrum[b]))
        .unwrap();
    assert!(
        (angles[peak].to_degrees() - 40.0).abs() <= 0.5,
        "IFB peak {}°",
        angles[peak].to_degrees()
    );
}

/// A one-point grid on an open interval reports its only angle.
#[test]
fn one_point_grid() {
    let est = MusicEstimator {
        angle_steps_num: 1,
        search_interval: (0.0, PI),
        ..MusicEstimator::default()
    };
    let data = kinect_tone(&est, 1000.0, 40.0, 1000);
    assert_eq!(est.estimate_doa_from_real(&data, 1, 1000.0), Ok(vec![0.0]));
}

/// Zero sources have nothing to find and return no angles. An empty search grid and
/// frequency 0 (every steering vector is the same, so the spectrum is flat) are errors.
#[test]
fn degenerate_configurations_find_nothing() {
    let est = MusicEstimator::default();
    let data = kinect_tone(&est, 1000.0, 40.0, 1000);
    let no_grid = MusicEstimator {
        angle_steps_num: 0,
        ..MusicEstimator::default()
    };
    assert!(matches!(
        no_grid.estimate_doa_from_real(&data, 1, 1000.0),
        Err(MusicError::InvalidAngleGrid { .. })
    ));
    assert_eq!(est.estimate_doa_from_real(&data, 0, 1000.0), Ok(vec![]));
    assert_eq!(
        est.estimate_doa_from_real(&data, 1, 0.0),
        Err(MusicError::InvalidFrequency(0.0))
    );
}

/// Very short recordings: two or three samples still give an estimate. A single sample
/// is silent, because removing its mean leaves nothing.
#[test]
fn very_short_data() {
    let est = MusicEstimator::default();
    let doa = |n| est.estimate_doa_from_real(&kinect_tone(&est, 1000.0, 40.0, n), 1, 1000.0);
    assert_eq!(doa(1), Err(MusicError::SilentData));
    for n in 2..=3 {
        assert!(doa(n).is_ok(), "n = {n}: {:?}", doa(n));
    }
}

/// IFB-MUSIC and bin selection at 48 kHz: bin frequencies follow `sample_rate`.
/// nfft = 480 gives 100 Hz bins, so the 1 kHz tone is bin 10.
#[test]
fn ifb_at_48_khz() {
    let est = MusicEstimator {
        sample_rate: 48000.0,
        ..MusicEstimator::default()
    };
    let data = kinect_tone(&est, 1000.0, 40.0, 48000);
    let bins = select_bins_by_energy(&data, 480, 20.0).unwrap();
    assert_eq!(bins, [10]);
    let (spectrum, angles) = est.ifb_music_spectrum(&data, 480, 1, Some(&bins)).unwrap();
    let argmax = (0..spectrum.len())
        .max_by(|&a, &b| spectrum[a].total_cmp(&spectrum[b]))
        .unwrap();
    let error = common::angular_error(angles[argmax].to_degrees(), &[40.0, 320.0]);
    assert!(error <= 0.5, "got {}°", angles[argmax].to_degrees());
}

// Every error the public API returns, one test per function.

use musicrs::{MusicError, MusicEstimator, select_bins_by_energy, stft};
use nalgebra::DMatrix;
use num_complex::Complex;
use std::f64::consts::PI;

const NFFT: usize = 160;

/// A 1 kHz tone, the same on all four Kinect microphones.
fn tone(n_samples: usize) -> DMatrix<f64> {
    DMatrix::from_fn(4, n_samples, |m, t| {
        (2.0 * PI * 1000.0 * t as f64 / 16000.0 + m as f64).cos()
    })
}

fn with_nan(mut data: DMatrix<f64>) -> DMatrix<f64> {
    data[(2, 10)] = f64::NAN;
    data
}

const TOO_MANY: MusicError = MusicError::TooManySources {
    n_sources: 4,
    n_antennas: 4,
};

#[test]
fn estimate_doa_from_real_errors() {
    let est = MusicEstimator::default();
    let doa = |data: &DMatrix<f64>, n_sources| est.estimate_doa_from_real(data, n_sources, 1000.0);
    assert_eq!(
        doa(&DMatrix::zeros(3, 100), 1),
        Err(MusicError::RowCountMismatch {
            expected: 4,
            got: 3
        })
    );
    assert_eq!(doa(&DMatrix::zeros(4, 0), 1), Err(MusicError::EmptyData));
    assert_eq!(
        doa(&with_nan(tone(1000)), 1),
        Err(MusicError::NonFiniteData)
    );
    let mut inf = tone(1000);
    inf[(0, 0)] = f64::INFINITY;
    assert_eq!(doa(&inf, 1), Err(MusicError::NonFiniteData));
    assert_eq!(
        doa(&DMatrix::zeros(4, 1000), 1),
        Err(MusicError::SilentData)
    );
    // A constant offset is removed with the mean, leaving silence
    assert_eq!(
        doa(&DMatrix::from_element(4, 1000, 0.3), 1),
        Err(MusicError::SilentData)
    );
    assert_eq!(doa(&tone(1000), 4), Err(TOO_MANY));
}

#[test]
fn estimate_doa_errors() {
    let est = MusicEstimator::default();
    let doa = |data: &DMatrix<Complex<f64>>| est.estimate_doa(data, 1, 1000.0);
    assert_eq!(
        doa(&DMatrix::from_element(3, 100, Complex::new(1.0, 0.5))),
        Err(MusicError::RowCountMismatch {
            expected: 4,
            got: 3
        })
    );
    assert_eq!(doa(&DMatrix::zeros(4, 0)), Err(MusicError::EmptyData));
    let mut nan = DMatrix::from_element(4, 100, Complex::new(1.0, 0.5));
    nan[(1, 1)] = Complex::new(0.0, f64::NAN);
    assert_eq!(doa(&nan), Err(MusicError::NonFiniteData));
    assert_eq!(doa(&DMatrix::zeros(4, 100)), Err(MusicError::SilentData));
}

#[test]
fn noise_subspace_and_spectrum_errors() {
    let est = MusicEstimator::default();
    for (rows, cols) in [(3, 3), (4, 3), (3, 4)] {
        assert_eq!(
            est.noise_subspace(&DMatrix::identity(rows, cols), 1),
            Err(MusicError::CovarianceShape {
                n_antennas: 4,
                rows,
                cols
            })
        );
    }
    assert_eq!(
        est.noise_subspace(&DMatrix::identity(4, 3), 1)
            .unwrap_err()
            .to_string(),
        "covariance matrix is 4 × 3, expected 4 × 4 (one row and column per antenna)"
    );
    let mut nan = DMatrix::identity(4, 4);
    nan[(0, 1)] = Complex::new(f64::NAN, 0.0);
    assert_eq!(est.noise_subspace(&nan, 1), Err(MusicError::NonFiniteData));
    assert_eq!(
        est.noise_subspace(&DMatrix::identity(4, 4), 4),
        Err(TOO_MANY)
    );
    assert_eq!(
        est.spectrum(&DMatrix::identity(3, 2), 1000.0),
        Err(MusicError::RowCountMismatch {
            expected: 4,
            got: 3
        })
    );
}

/// Constant data is silent once its mean is removed, whatever the constant and length:
/// the rounding residue stays below the silence threshold.
#[test]
fn constant_data_is_silent() {
    let est = MusicEstimator::default();
    for c in [0.3, -0.1, 1.0 / 3.0, PI * 1e5, 1e6 + 0.3, 7e-9, 1e12 / 7.0] {
        for n in [2, 3, 1000, 1601, 16000] {
            let data = DMatrix::from_element(4, n, c);
            assert_eq!(
                est.estimate_doa_from_real(&data, 1, 1000.0),
                Err(MusicError::SilentData),
                "c = {c}, n = {n}"
            );
            if n >= NFFT {
                assert_eq!(
                    est.ifb_music_spectrum(&data, NFFT, 1, None),
                    Err(MusicError::SilentData),
                    "IFB: c = {c}, n = {n}"
                );
            }
        }
    }
}

/// An unusable angle grid is an error wherever the grid is searched. `new` does not check
/// it, because the fields are public and can change after construction.
#[test]
fn invalid_angle_grid_errors() {
    let data = tone(1024);
    let n = MusicEstimator::default().n_antennas();
    for (steps, interval) in [
        (0, (0.0, PI)),
        (360, (PI, 0.0)),
        (360, (1.0, 1.0)),
        (360, (0.0, f64::NAN)),
        (360, (f64::NEG_INFINITY, 0.0)),
    ] {
        let est = MusicEstimator::new(
            MusicEstimator::default().antenna_positions,
            steps,
            interval,
            16000.0,
        );
        let is_grid_err = |e: MusicError| matches!(e, MusicError::InvalidAngleGrid { .. });
        assert!(is_grid_err(
            est.estimate_doa_from_real(&data, 1, 1000.0).unwrap_err()
        ));
        assert!(is_grid_err(
            est.ifb_music_spectrum(&data, NFFT, 1, None).unwrap_err()
        ));
        assert!(is_grid_err(
            est.spectrum(&DMatrix::identity(n, n - 1), 1000.0)
                .unwrap_err()
        ));
    }
}

#[test]
fn ifb_music_spectrum_errors() {
    let est = MusicEstimator::default();
    let data = tone(1600);
    let ifb = |data: &DMatrix<f64>, nfft, n_sources, bins: Option<&[usize]>| {
        est.ifb_music_spectrum(data, nfft, n_sources, bins)
            .map(|_| ())
    };
    assert_eq!(
        ifb(&DMatrix::zeros(3, 1600), NFFT, 1, None),
        Err(MusicError::RowCountMismatch {
            expected: 4,
            got: 3
        })
    );
    assert_eq!(
        ifb(&DMatrix::zeros(0, 1600), NFFT, 1, None),
        Err(MusicError::RowCountMismatch {
            expected: 4,
            got: 0
        })
    );
    assert_eq!(
        ifb(&DMatrix::zeros(4, 0), NFFT, 1, None),
        Err(MusicError::EmptyData)
    );
    assert_eq!(
        ifb(&with_nan(data.clone()), NFFT, 1, None),
        Err(MusicError::NonFiniteData)
    );
    assert_eq!(ifb(&data, NFFT, 4, None), Err(TOO_MANY));
    assert_eq!(ifb(&data, 0, 1, None), Err(MusicError::InvalidNfft));
    assert_eq!(
        ifb(&tone(NFFT - 1), NFFT, 1, None),
        Err(MusicError::DataShorterThanWindow {
            nfft: NFFT,
            samples: NFFT - 1
        })
    );
    // nfft = 1 has only the DC bin, which `None` skips
    assert_eq!(ifb(&data, 1, 1, None), Err(MusicError::NoUsableBins));
    assert_eq!(
        ifb(&data, NFFT, 1, Some(&[])),
        Err(MusicError::NoUsableBins)
    );
    assert_eq!(
        ifb(&data, NFFT, 1, Some(&[NFFT / 2 + 1, 10_000])),
        Err(MusicError::NoUsableBins)
    );
    assert_eq!(
        ifb(&DMatrix::zeros(4, 1600), NFFT, 1, None),
        Err(MusicError::SilentData)
    );
    // The tone is bin 10; bin 30 holds no power
    assert_eq!(
        ifb(&data, NFFT, 1, Some(&[30])),
        Err(MusicError::SilentData)
    );
}

/// Bins without power are skipped rather than mixed into the geometric mean.
#[test]
fn ifb_music_spectrum_skips_silent_bins() {
    let est = MusicEstimator::default();
    let data = tone(1600);
    let (only, _) = est.ifb_music_spectrum(&data, NFFT, 1, Some(&[10])).unwrap();
    let (with_silent, _) = est
        .ifb_music_spectrum(&data, NFFT, 1, Some(&[10, 30, 50]))
        .unwrap();
    assert_eq!(only, with_silent);
}

/// The estimator's own fields are checked where they are used: the sample rate and
/// antenna positions by every function that builds steering vectors.
#[test]
fn invalid_estimator_errors() {
    let data = tone(1600);
    let noise = DMatrix::identity(4, 3);
    let check = |est: &MusicEstimator, expected: MusicError| {
        assert_eq!(
            est.estimate_doa_from_real(&data, 1, 1000.0),
            Err(expected.clone())
        );
        let complex = data.map(|x| Complex::new(x, 0.0));
        assert_eq!(est.estimate_doa(&complex, 1, 1000.0), Err(expected.clone()));
        assert_eq!(
            est.ifb_music_spectrum(&data, NFFT, 1, None).map(|_| ()),
            Err(expected.clone())
        );
        assert_eq!(est.spectrum(&noise, 1000.0).map(|_| ()), Err(expected));
    };
    for sr in [0.0, -16000.0, f64::NAN, f64::INFINITY] {
        let est = MusicEstimator {
            sample_rate: sr,
            ..MusicEstimator::default()
        };
        // NaN != NaN, so compare the error's text for it
        if sr.is_nan() {
            assert_eq!(
                est.estimate_doa_from_real(&data, 1, 1000.0)
                    .unwrap_err()
                    .to_string(),
                "sample rate must be finite and positive, got NaN Hz"
            );
        } else {
            check(&est, MusicError::InvalidSampleRate(sr));
        }
    }
    for bad in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
        let mut est = MusicEstimator::default();
        est.antenna_positions[2][1] = bad;
        check(&est, MusicError::InvalidAntennaPosition { index: 2 });
    }
    // A search interval wider than 2π visits directions twice; exactly 2π is fine
    let wide = MusicEstimator {
        search_interval: (0.0, 4.0 * PI),
        angle_steps_num: 1440,
        ..MusicEstimator::default()
    };
    check(
        &wide,
        MusicError::InvalidAngleGrid {
            angle_steps_num: 1440,
            search_interval: (0.0, 4.0 * PI),
        },
    );
    let shifted = MusicEstimator {
        search_interval: (-PI, PI),
        ..MusicEstimator::default()
    };
    assert!(shifted.estimate_doa_from_real(&data, 1, 1000.0).is_ok());
}

/// The signal frequency must be finite and positive, for every function that takes one.
#[test]
fn invalid_frequency_errors() {
    let est = MusicEstimator::default();
    let data = tone(1600);
    let complex = data.map(|x| Complex::new(x, 0.0));
    for freq in [0.0, -1000.0, f64::INFINITY, f64::NEG_INFINITY] {
        let expected = Err(MusicError::InvalidFrequency(freq));
        assert_eq!(est.estimate_doa_from_real(&data, 1, freq), expected);
        assert_eq!(est.estimate_doa(&complex, 1, freq), expected);
        assert_eq!(
            est.spectrum(&DMatrix::identity(4, 3), freq).map(|_| ()),
            expected.map(|_| ())
        );
    }
    assert!(matches!(
        est.estimate_doa_from_real(&data, 1, f64::NAN),
        Err(MusicError::InvalidFrequency(f)) if f.is_nan()
    ));
}

/// IFB never uses the DC bin: it has no direction information.
#[test]
fn ifb_music_spectrum_ignores_dc_bin() {
    let est = MusicEstimator::default();
    let data = tone(1600).map(|x| x + 0.5);
    assert_eq!(
        est.ifb_music_spectrum(&data, NFFT, 1, Some(&[0]))
            .map(|_| ()),
        Err(MusicError::NoUsableBins)
    );
    assert_eq!(
        est.ifb_music_spectrum(&data, NFFT, 1, Some(&[0, 10])),
        est.ifb_music_spectrum(&data, NFFT, 1, Some(&[10]))
    );
}

/// The complex entry point checks the source count and the angle grid itself.
#[test]
fn estimate_doa_parameter_errors() {
    let complex = tone(1000).map(|x| Complex::new(x, 0.0));
    assert_eq!(
        MusicEstimator::default().estimate_doa(&complex, 4, 1000.0),
        Err(TOO_MANY)
    );
    let no_grid = MusicEstimator {
